        for (oid, comp, qty, e) in demands:
            cands = []
            for mat in component_materials(comp):
                for lot in lots_by_material.get(mat, []):
                    if lot['expiry'] >= e:
                        cands.append(lot)
            demand_candidates.append((oid, comp, qty, e, cands))

